import Foundation

/// One catalogue calibre with its dimensions in millimetres and a side-view outline.
/// Generated by tools/generate_data.py into Resources/Cartridges.json.
struct Cartridge: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    /// German category name from the catalogue, see `CartridgeCatalog.Category`.
    let category: String
    /// rimless, rimmed, belted, rimfire, shot, ball, minie or pellet.
    let kind: String
    let aliases: [String]
    /// Printable alternative names, e.g. "9 mm Luger" for 9x19 mm.
    let displayAliases: [String]
    /// No longer in regular factory production (only surplus, boutique loads or reloading).
    /// Matching skips these unless the «Veraltete Kaliber» switch is on.
    let obsolete: Bool
    /// Hardly ever found, so a photo or measurement that matches it is more likely a similar,
    /// common calibre (calibre-data RARE). Shown with the «Selten» tag.
    let rare: Bool
    /// The state that introduced the calibre (calibre-data ORIGIN); nil for gauges, balls, pellets,
    /// blanks and calibres whose origin is still open.
    let country: Country?
    /// In common use worldwide (calibre-data WORLDWIDE), shown as a globe next to the flag.
    /// Independent of `country`: 9x19 mm is German and worldwide.
    let worldwide: Bool
    /// A crimped blank (power-tool load, starter pistol blank): no bullet, the case is the whole cartridge.
    let blank: Bool
    let dimensions: Dimensions
    let outline: Outline
    /// Nil for rimfire and for balls, Minié bullets and pellets.
    let primer: Primer?
    /// The painted bullet tips, case bases and primer rings of military loads (calibre-data [[colour_codes]]);
    /// empty for most calibres.
    let colourCodes: [ColourCode]

    /// One colour code: what a painted tip, base or primer ring means (Raven, 2026-11-11: shown on the calibre page).
    struct ColourCode: Decodable, Hashable {
        /// "tip" (the bullet tip), "base" (the case head) or "annulus" (the lacquer ring around the primer).
        let part: String
        /// Colour names; a tip's from the tip down (["red", "silver"] is a red tip above a silver band), a base or ring has one.
        let colours: [String]
        /// What the code means, combined: ["armour-piercing", "incendiary"] is an API load.
        let meaning: [String]
        /// The loads that carry it, e.g. "US M20, Swiss M.65".
        let description: String?
        let countries: [Country]

        /// German title of a meaning, used as localization key.
        static func title(_ meaning: String) -> String {
            switch meaning {
            case "ball": "Standardgeschoss"
            case "armour-piercing": "Panzerbrechend"
            case "incendiary": "Brand"
            case "explosive": "Spreng"
            case "tracer": "Leuchtspur"
            case "spotting": "Markierung"
            case "subsonic": "Unterschall"
            case "frangible": "Zerfallend"
            case "proof": "Beschuss"
            case "reduced-charge": "Reduzierte Ladung"
            default: meaning
            }
        }

        /// German name of a colour, used as localization key (what VoiceOver reads for the swatch); capitalised,
        /// as the string extractor takes a lower-case word for a symbol name.
        static func colourName(_ colour: String) -> String {
            switch colour {
            case "black": "Schwarz"
            case "white": "Weiss"
            case "grey": "Grau"
            case "silver": "Silber"
            case "red": "Rot"
            case "orange": "Orange"
            case "yellow": "Gelb"
            case "green": "Grün"
            case "blue": "Blau"
            case "purple": "Violett"
            case "brown": "Braun"
            default: colour
            }
        }
    }

    /// A country from calibre-data ORIGIN.
    struct Country: Decodable, Hashable {
        /// ISO code; RUE, AH, SU and CS for former states, NATO for the alliance.
        let code: String
        /// German name, used as localization key.
        let name: String
        /// Flag emoji; nil for former states and unions, whose flag `DrawnFlag` draws.
        let flag: String?
    }

    /// The primer in the centre of the case head (that of the original factory ammunition).
    struct Primer: Decodable, Hashable {
        /// small-pistol, large-pistol, small-rifle, large-rifle, shotshell-209, bmg-35 or berdan-nitro.
        let type: String
        /// Cup diameter in mm.
        let diameter: Double

        /// German title, used as localization key.
        var title: String {
            switch type {
            case "small-pistol": "Pistole klein"
            case "large-pistol": "Pistole gross"
            case "small-rifle": "Büchse klein"
            case "large-rifle": "Büchse gross"
            case "miniature": "Miniatur"
            case "shotshell-209": "Schrot (209)"
            case "bmg-35": ".50 BMG (#35)"
            case "berdan-nitro": "Berdan Nitro (.254)"
            default: type
            }
        }
    }

    struct Dimensions: Decodable, Hashable {
        let rim: Double
        let base: Double
        /// Only for bottleneck cases.
        let shoulder: Double?
        let neck: Double
        /// 0 for round balls, Minié bullets and pellets (no case).
        let caseLength: Double
        let overallLength: Double
        let bullet: Double
    }

    /// Side view in millimetres: tip at y = 0, base at y = `height`, centred in `width`.
    struct Outline: Decodable, Hashable {
        let width: Double
        let height: Double
        let `case`: String?
        let head: String?
        let bullet: String?
        /// Paper band drawn over the bullet (paper-patched GP 1890 bullet); nil for jacketed bullets.
        /// Not part of the silhouette: `bullet` already covers it.
        let patch: String?
        /// Tip drawn over the bullet (not part of the silhouette): bare lead of a soft point, or a
        /// plastic tip when `tipMaterial` is "polymer".
        let tip: String?
        let tipMaterial: String?
        /// "steel" for a steel-capped nose or a steel BB, "lead" for a bare lead bullet, "plastic"
        /// for an airsoft BB; nil means copper (or lead without a case).
        let bulletMaterial: String?
        /// "copper", "steel" (lacquered), "nickel", "aluminium", "paper" or "hybrid" where the case is not brass.
        let caseMaterial: String?
        /// "steel" for the steel head of a hybrid case (.277 Fury); nil means brass.
        let headMaterial: String?
    }

    var hasCase: Bool { dimensions.caseLength > 0 }

    /// A loaded shotshell's length depends on its crimp: a folded (star) crimp ends shorter than the
    /// catalogue's length, a roll crimp a little longer. Raven's 12/70 (catalogue 64.0 mm) measured
    /// 57.8 mm (B&P EasyShot Steel), 58.2 mm (Clever Mirage Caccia) and 65.5 mm (Remington), 2026-11-08.
    static let shellShortest = 0.9
    static let shellLongest = 1.03

    /// The lengths a loaded round of this calibre can have, in mm: the catalogue's overall length, or for
    /// a shotshell the range its crimps give (`shellShortest`, `shellLongest`).
    var overallLengths: ClosedRange<Double> {
        let length = dimensions.overallLength
        return kind == "shot" ? length * Self.shellShortest...length * Self.shellLongest : length...length
    }

    /// Diameter of the case head seen from below: the rim, or the base where it is wider.
    var headDiameter: Double { max(dimensions.rim, dimensions.base) }

    /// All names the cartridge is known by, for search.
    var allNames: [String] { [name] + displayAliases + aliases }
}

/// What the 1:1 comparison sorts its cartridges by (Einstellungen, Raven 2026-11-08): the case, as the
/// standard, or the whole round. A photo with a LiDAR size may keep the matcher's order instead.
enum CompareLength: String, CaseIterable, Identifiable {
    case caseLength, overallLength

    var id: String { rawValue }
    static let key = "compareLength"
    /// The setting as stored: the case length until the user chooses otherwise.
    static var current: CompareLength { UserDefaults.standard.string(forKey: key).flatMap(CompareLength.init) ?? .caseLength }
    /// German title, used as localization key.
    var title: String { self == .caseLength ? "Hülsenlänge" : "Gesamtlänge" }
}

extension Cartridge {
    /// The length the 1:1 comparison sorts by; rounds without a case (balls, pellets) by their whole length.
    func compareLength(_ by: CompareLength) -> Double {
        by == .caseLength && hasCase ? dimensions.caseLength : dimensions.overallLength
    }
}

extension [Cartridge] {
    /// Shortest first by `by`, then narrowest (the Ø under each 1:1 drawing); equal ones keep their order.
    func byLength(_ by: CompareLength = .current) -> [Cartridge] {
        sorted { ($0.compareLength(by), $0.headDiameter) < ($1.compareLength(by), $1.headDiameter) }
    }

    /// Calibres picked for a 1:1 comparison, with `c` added (or removed when picked already). They
    /// stay in length order, not the order they were picked in, and are compared in that order.
    func toggling(_ c: Cartridge, by: CompareLength = .current) -> [Cartridge] {
        contains(c) ? filter { $0 != c } : (self + [c]).byLength(by)
    }
}
